import unittest


def _make_test(expected):
    # target LegacyTestMeta pattern: a factory produces a function with
    # __name__ == "test", the class attribute is named differently.
    def test(self):
        assert self.value == expected
    return test


class TestGenerated(unittest.TestCase):
    value = None


for _i, _val in enumerate(["a", "bb", "ccc"]):
    # subclasses with different values; methods are generated by a metaclass-like loop
    def _mk(v):
        def test(self):
            assert self.value == v
        return test
    globals()[f"TestGen{_i}"] = type(f"TestGen{_i}", (unittest.TestCase,), {
        "value": _val,
        f"test_len_{_i}": _mk(_val),
    })


def _no_wraps(fn):
    # regression: a decorator without functools.wraps - __name__ == "wrapper"
    def wrapper(self):
        return fn(self)
    return wrapper


class TestDecorated(unittest.TestCase):
    @_no_wraps
    def test_wrapped(self):
        assert True

    @_no_wraps
    def test_wrapped2(self):
        assert 2 + 2 == 4
